26	
27	export default function TicketDetailPage({ params }: { params: Promise<{ id: string }> }) {
28	  const { id } = use(params);
29	  const router = useRouter();
30	  const { push: pushToast } = useToast();
31	
32	  const [t, setTicket] = useState<Ticket | null>(null);
33	  const [prop, setProp] = useState<Property | null>(null);
34	  const [vendor, setVendor] = useState<Vendor | null>(null);
35	  const [loadError, setLoadError] = useState<string | null>(null);
