37	
38	  const [transcriptOpen, setTranscriptOpen] = useState(false);
39	  const [reasoningOpen, setReasoningOpen] = useState(false);
40	
41	  // -----------------------------------------------------------------------
42	  // Sprint 2: Streaming action cards state
43	  // -----------------------------------------------------------------------
44	  const [actions, setActions] = useState<AgentAction[]>([]);
45	  const [agentRunning, setAgentRunning] = useState(false);
46	  const [agentDone, setAgentDone] = useState(false);
47	  const [agentText, setAgentText] = useState("");
48	  const abortRef = useRef<AbortController | null>(null);
49	  const actionsEndRef = useRef<HTMLDivElement>(null);
50	
51	  // Load any existing actions for this ticket (from previous runs)
52	  useEffect(() => {
53	    let cancelled = false;
54	    api.tickets.actions(id).then((existing) => {
55	      if (!cancelled && existing.length > 0) {
56	        setActions(existing);
57	      }
58	    }).catch(() => {/* ignore — actions table may be empty */});
59	    return () => { cancelled = true; };
60	  }, [id]);
61	
62	  // Auto-scroll to bottom of actions stream
63	  useEffect(() => {
64	    actionsEndRef.current?.scrollIntoView({ behavior: "smooth" });
65	  }, [actions.length]);
66	
67	  function upsertAction(incoming: AgentAction) {
68	    setActions((prev) => {
69	      const idx = prev.findIndex((a) => a.id === incoming.id);
70	      if (idx >= 0) {
71	        const updated = [...prev];
72	        updated[idx] = incoming;
73	        return updated;
74	      }
75	      return [...prev, incoming];
76	    });
77	  }
