103	              variant: "destructive",
104	            });
105	          },
106	          signal: ctrl.signal,
107	        }
108	      );
109	    } catch (err) {
110	      if (err instanceof Error && err.name === "AbortError") return;
111	    } finally {
112	      setAgentRunning(false);
113	    }
114	  }
115	
116	  function stopAgentRun() {
117	    abortRef.current?.abort();
118	    setAgentRunning(false);
119	  }
120	
121	  // -----------------------------------------------------------------------
122	  // Ticket loading
123	  // -----------------------------------------------------------------------
124	
125	  useEffect(() => {
126	    let cancelled = false;
127	    setTicket(null);
128	    setProp(null);
129	    setVendor(null);
130	    setLoadError(null);
131	    (async () => {
132	      try {
133	        const ticket = await api.tickets.get(id);
134	        if (cancelled) return;
135	        setTicket(ticket);
136	        const [property, v] = await Promise.all([
137	          api.properties.get(ticket.propertyId),
138	          ticket.proposal ? api.vendors.get(ticket.proposal.proposedAction.vendorId) : Promise.resolve(null),
139	        ]);
140	        if (cancelled) return;
141	        setProp(property);
142	        setVendor(v);
143	      } catch (err) {
144	        if (cancelled) return;
145	        if (err instanceof ApiError && err.status === 404) {
146	          notFound();
