365	
366	                {/* Reasoning collapsed by default */}
367	                <button
368	                  onClick={() => setReasoningOpen((o) => !o)}
369	                  className="mt-4 flex w-full items-center justify-between rounded-md border-t pt-3 text-left text-sm hover:bg-accent/50"
370	                >
