384	                    </div>
385	                  </div>
386	                )}
387	              </CardContent>
388	            </Card>
389	          )}
390	
391	          {/* ================================================================
392	              Sprint 2: AGENT ACTION STREAM
393	              Shows a live stream of what Hermes is doing / has proposed.
394	              ================================================================ */}
395	          <Card className="overflow-hidden">
396	            <CardContent className="p-0">
397	              {/* Header */}
398	              <div className="flex items-center justify-between border-b px-5 py-3">
399	                <div className="flex items-center gap-2">
400	                  <Bot className="h-4 w-4 text-blue-500" />
401	                  <span className="text-sm font-semibold">Hermes agent actions</span>
402	                  {agentRunning && (
403	                    <Badge variant="muted" className="animate-pulse text-xs">
404	                      <Loader2 className="mr-1 h-3 w-3 animate-spin" />
405	                      running…
406	                    </Badge>
407	                  )}
408	                  {agentDone && !agentRunning && actions.length > 0 && (
409	                    <Badge variant="success" className="text-xs">
410	                      <CheckCircle2 className="mr-1 h-3 w-3" />
411	                      complete
412	                    </Badge>
413	                  )}
414	                </div>
415	                {agentRunning ? (
416	                  <Button size="sm" variant="ghost" className="h-7 text-xs" onClick={stopAgentRun}>
417	                    Stop
418	                  </Button>
419	                ) : (
420	                  <Button
421	                    size="sm"
422	                    variant="outline"
423	                    className="h-7 text-xs gap-1"
424	                    onClick={startAgentRun}
425	                    disabled={agentRunning}
426	                  >
427	                    <Play className="h-3 w-3" />
428	                    {actions.length > 0 ? "Re-run Hermes" : "Run Hermes"}
429	                  </Button>
430	                )}
431	              </div>
432	
433	              {/* Action cards stream */}
434	              {actions.length === 0 && !agentRunning ? (
435	                <div className="p-8 text-center text-sm text-muted-foreground">
436	                  <Bot className="mx-auto mb-2 h-6 w-6 opacity-30" />
437	                  <p>Click <strong>Run Hermes</strong> to have the agent analyse this ticket</p>
438	                  <p className="mt-1 text-xs">
439	                    The agent will read property context, check policies, and propose appropriate actions.
440	                  </p>
441	                </div>
442	              ) : (
443	                <div className="max-h-[600px] overflow-auto p-4 space-y-2">
444	                  {actions.map((action) => (
445	                    <div
446	                      key={action.id}
447	                      className="animate-in fade-in slide-in-from-bottom-2 duration-300"
448	                    >
449	                      <ActionCard
450	                        action={action}
451	                        onConfirmed={() => refetchTicket()}
452	                      />
453	                    </div>
454	                  ))}
455	
456	                  {/* Agent reasoning text (streaming) */}
457	                  {agentText && (
458	                    <Card className="border-muted/50 bg-muted/20">
459	                      <CardContent className="p-3 text-xs text-muted-foreground leading-relaxed whitespace-pre-wrap">
460	                        <span className="font-semibold text-foreground">Hermes: </span>
461	                        {agentText}
462	                        {agentRunning && <span className="inline-block h-3 w-0.5 animate-pulse bg-foreground ml-0.5" />}
463	                      </CardContent>
464	                    </Card>
465	                  )}
466	
467	                  <div ref={actionsEndRef} />
468	                </div>
469	              )}
470	            </CardContent>
471	          </Card>
472	
473	          {/* ================================================================
474	              Escalation notice (Sprint 2)
475	              ================================================================ */}
476	          {t.escalatedAt && (
477	            <Card className="border-destructive/40 bg-destructive/5">
478	              <CardContent className="p-4">
479	                <div className="flex items-start gap-2">
480	                  <AlertTriangle className="mt-0.5 h-4 w-4 text-destructive" />
481	                  <div>
482	                    <div className="text-sm font-semibold text-destructive">Escalated to human operator</div>
483	                    <div className="mt-1 text-xs text-muted-foreground whitespace-pre-wrap">{t.escalationReason}</div>
484	                  </div>
485	                </div>
486	              </CardContent>
487	            </Card>
488	          )}
489	
490	          {/* Vendor job status (when in flight or completed) */}
491	          {t.vendorJob && (
492	            <Card>
493	              <CardContent className="p-5">
494	                <div className="mb-3 flex items-center gap-2">
495	                  <Wrench className="h-4 w-4 text-muted-foreground" />
496	                  <h3 className="text-sm font-semibold">Vendor job</h3>
497	                </div>
498	                <ul className="space-y-2 text-sm">
499	                  <li className="flex justify-between"><span className="text-muted-foreground">Sent</span><span>{new Date(t.vendorJob.sentAt).toLocaleString("de-DE")}</span></li>
500	                  <li className="flex justify-between"><span className="text-muted-foreground">Accepted</span><span>{t.vendorJob.accepted ? "Yes" : "Pending"}</span></li>
501	                  {t.vendorJob.scheduledFor && <li className="flex justify-between"><span className="text-muted-foreground">Scheduled</span><span>{new Date(t.vendorJob.scheduledFor).toLocaleString("de-DE")}</span></li>}
502	                  {t.vendorJob.completedAt && <li className="flex justify-between"><span className="text-muted-foreground">Completed</span><span>{new Date(t.vendorJob.completedAt).toLocaleString("de-DE")}</span></li>}
503	                  {t.vendorJob.finalCostEur != null && <li className="flex justify-between"><span className="text-muted-foreground">Final cost</span><span className="font-medium">{formatEur(t.vendorJob.finalCostEur)}</span></li>}
504	                  {t.vendorJob.notes && <li className="text-muted-foreground">"{t.vendorJob.notes}"</li>}
505	                </ul>
506	              </CardContent>
507	            </Card>
508	          )}
509	
510	          {/* MEMORY DECISION — only after vendor completion AND status === pending */}
511	          {showMemoryDecision && (
512	            <Card className="border-emerald-500/30 bg-emerald-500/5">
513	              <CardContent className="p-5">
514	                <div className="mb-2 flex items-center gap-2">
515	                  <Sparkles className="h-4 w-4 text-emerald-500" />
516	                  <div className="text-xs font-semibold uppercase tracking-wider text-emerald-600 dark:text-emerald-400">Memory decision · vendor closed the job</div>
517	                </div>
518	                <p className="mb-3 text-sm">
519	                  Save to <code className="font-mono text-xs">context.md v{t.memoryProposal!.targetVersion}</code>:
520	                </p>
521	                <blockquote className="mb-4 rounded border-l-2 border-emerald-400 bg-background px-3 py-2 text-sm">
522	                  {t.memoryProposal!.text}
523	                </blockquote>
524	                <div className="flex gap-2">
525	                  <Button variant="success" onClick={handleSaveMemory} disabled={mutating !== null}>
526	                    {mutating === "saveMemory" ? <Loader2 className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />}
527	                    Save to memory
528	                  </Button>
529	                  <Button variant="outline" disabled={mutating !== null}><FileEdit className="h-4 w-4" />Edit</Button>
530	                  <Button variant="ghost" onClick={handleSkipMemory} disabled={mutating !== null}>
531	                    {mutating === "skipMemory" ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
532	                    Skip
533	                  </Button>
534	                </div>
535	              </CardContent>
536	            </Card>
537	          )}
538	
539	          {memorySaved && (
540	            <Card className="border-emerald-500/40 bg-emerald-500/10">
541	              <CardContent className="p-4 text-sm text-emerald-600 dark:text-emerald-400">
542	                <CheckCircle2 className="mr-2 inline h-4 w-4" />
543	                Memory saved to <code className="font-mono text-xs">context.md v{t.memoryProposal?.targetVersion}</code>. Ticket resolved.
544	              </CardContent>
545	            </Card>
546	          )}
547	
548	          {memorySkipped && (
549	            <Card>
550	              <CardContent className="p-4 text-sm text-muted-foreground">
551	                Memory write skipped. Ticket closed without context update.
552	              </CardContent>
553	            </Card>
554	          )}
555	
556	          {/* SOURCE — call transcript or email */}
557	          {t.callSession && (
558	            <Card>
559	              <CardContent className="p-5">
560	                <button
561	                  onClick={() => setTranscriptOpen((o) => !o)}
562	                  className="flex w-full items-center justify-between text-left"
563	                >
564	                  <div className="flex items-center gap-2">
565	                    <Phone className="h-4 w-4 text-muted-foreground" />
566	                    <span className="text-sm font-semibold">Call transcript</span>
567	                    <Badge variant="muted" className="font-mono">{t.callSession.duration}</Badge>
568	                    <span className="text-xs text-muted-foreground">noise reduction {t.callSession.noiseReductionDb} dB</span>
569	                  </div>
570	                  {transcriptOpen ? <ChevronDown className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
571	                </button>
572	                {!transcriptOpen && (
573	                  <p className="mt-2 text-sm text-muted-foreground">{t.callSession.summary}</p>
574	                )}
575	                {transcriptOpen && (
576	                  <div className="mt-4 space-y-2 max-h-80 overflow-auto rounded border bg-muted/20 p-3">
577	                    {t.callSession.transcript.map((line, i) => (
578	                      <div key={i} className={cn("flex gap-3 text-sm", line.spk === "tenant" ? "" : "text-muted-foreground")}>
579	                        <span className="w-12 shrink-0 font-mono text-[10px] text-muted-foreground">{line.t}</span>
580	                        <span className="w-14 shrink-0 text-[10px] uppercase">{line.spk}</span>
581	                        <div className="flex-1">
582	                          <div>{line.text}</div>
583	                          <div className="text-[11px] italic text-muted-foreground">{line.en}</div>
584	                        </div>
585	                      </div>
586	                    ))}
587	                  </div>
588	                )}
589	              </CardContent>
590	            </Card>
591	          )}
592	
593	          {t.emailBody && (
594	            <Card>
595	              <CardContent className="p-5">
596	                <div className="mb-2 flex items-center gap-2">
597	                  <Mail className="h-4 w-4 text-muted-foreground" />
598	                  <span className="text-sm font-semibold">Email</span>
599	                </div>
600	                <pre className="whitespace-pre-wrap text-sm font-sans">{t.emailBody}</pre>
601	              </CardContent>
602	            </Card>
603	          )}
604	        </div>
605	
606	        {/* RIGHT 1/3 — context */}
607	        <aside className="space-y-4">
608	          <Card>
609	            <CardContent className="p-4">
610	              <div className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Property</div>
611	              <Link href={prop ? `/property/${prop.id}/context` : "#"} className="mt-1 block text-sm font-medium hover:underline">
612	                {prop?.name ?? "—"}
613	              </Link>
614	              <div className="mt-1 text-xs text-muted-foreground">context.md v{prop?.contextVersion ?? "—"}</div>
615	              <Separator className="my-3" />
616	              <div className="space-y-1 text-xs">
617	                <div><span className="text-muted-foreground">Phone: </span>{prop?.phone ?? "—"}</div>
618	                <div><span className="text-muted-foreground">Email: </span>{prop?.email ?? "—"}</div>
619	                <div><span className="text-muted-foreground">Open tickets: </span>{prop?.openTickets ?? "—"}</div>
620	              </div>
621	            </CardContent>
622	          </Card>
623	
624	          <Card>
625	            <CardContent className="p-4">
626	              <div className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Activity</div>
627	              <ul className="mt-2 space-y-2 text-xs">
628	                <li className="flex gap-2"><Clock className="mt-0.5 h-3 w-3 text-muted-foreground" /><span>Ticket opened — {timeAgo(t.createdAt)} ago</span></li>
629	                <li className="flex gap-2"><MessageSquare className="mt-0.5 h-3 w-3 text-muted-foreground" /><span>Triage agent classified</span></li>
630	                {t.proposal && <li className="flex gap-2"><Sparkles className="mt-0.5 h-3 w-3 text-blue-500 dark:text-blue-400" /><span>Hermes proposed action</span></li>}
631	                {isApproved && <li className="flex gap-2"><CheckCircle2 className="mt-0.5 h-3 w-3 text-emerald-700" /><span>Operator approved</span></li>}
632	                {t.vendorJob?.completedAt && <li className="flex gap-2"><Wrench className="mt-0.5 h-3 w-3 text-emerald-700" /><span>Vendor reported completion</span></li>}
633	                {memorySaved && <li className="flex gap-2"><Sparkles className="mt-0.5 h-3 w-3 text-emerald-700" /><span>Memory committed to v{t.memoryProposal?.targetVersion}</span></li>}
634	                {t.escalatedAt && <li className="flex gap-2"><AlertTriangle className="mt-0.5 h-3 w-3 text-destructive" /><span>Escalated to human</span></li>}
635	                {actions.length > 0 && <li className="flex gap-2"><Bot className="mt-0.5 h-3 w-3 text-blue-400" /><span>{actions.length} agent action{actions.length !== 1 ? "s" : ""} recorded</span></li>}
636	              </ul>
637	            </CardContent>
638	          </Card>
639	
640	          {vendor && (
641	            <Card>
642	              <CardContent className="p-4">
643	                <div className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Proposed vendor</div>
644	                <Link href={`/vendor/${vendor.id}`} className="mt-1 block text-sm font-medium hover:underline">{vendor.name}</Link>
645	                <div className="mt-2 space-y-1 text-xs">
646	                  <div><span className="text-muted-foreground">Trade: </span>{vendor.trade}</div>
647	                  <div><span className="text-muted-foreground">Rating: </span>{vendor.rating} / 5</div>
648	                  <div><span className="text-muted-foreground">SLA: </span>{vendor.slaHours}h</div>
649	                  <div><span className="text-muted-foreground">Phone: </span>{vendor.phone}</div>
650	                </div>
651	              </CardContent>
652	            </Card>
653	          )}
654	
655	          {/* Sprint 2: Agent actions summary in sidebar */}
656	          {actions.length > 0 && (
657	            <Card>
658	              <CardContent className="p-4">
659	                <div className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-2">
660	                  Agent summary
661	                </div>
662	                <ul className="space-y-1 text-xs">
663	                  {actions.filter((a) => a.status === "proposed").length > 0 && (
664	                    <li className="flex gap-2 text-amber-600">
665	                      <span>⊙</span>
666	                      <span>{actions.filter((a) => a.status === "proposed").length} proposal(s) awaiting review</span>
667	                    </li>
668	                  )}
669	                  {actions.filter((a) => a.actionType === "escalate_to_human").length > 0 && (
670	                    <li className="flex gap-2 text-destructive">
671	                      <AlertTriangle className="h-3 w-3 mt-0.5" />
672	                      <span>Escalation proposed</span>
673	                    </li>
674	                  )}
675	                  <li className="flex gap-2 text-muted-foreground">
676	                    <span>↳</span>
677	                    <span>{actions.filter((a) => a.actionType === "read").length} context lookups</span>
678	                  </li>
679	                </ul>
680	              </CardContent>
681	            </Card>
682	          )}
